function processRefs (target) {
  const refs = target.$refs
  if (refs) {
    Object.keys(refs).forEach((key) => {
      const matched = /^__mpx_ref_(.+)__$/.exec(key)
      const rKey = matched && matched[1]
      if (rKey) {
