          } else {
            refs[rKey] = ref
          }
        }
      }
    })
  }
}

export default function getRefsMixin () {
  return {
    [BEFOREMOUNT] () {
      processRefs(this)
    },
    [UPDATED] () {
      processRefs(this)
    }
  }
